<script setup lang="ts">import {Head,Link,router} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';const p=defineProps<{campaign:any}>();const submit=()=>router.post(`/admin/ad-campaigns/${p.campaign.id}/submit`);const decide=(decision:string)=>router.post(`/admin/ad-campaigns/${p.campaign.id}/decision`,{decision,rejection_reason:decision==='reject'?prompt('Reason for rejection')||'Rejected':''});</script><template><Head :title="campaign.name"/><div class="space-y-6 p-6"><div class="flex justify-between"><PageHeader :title="campaign.name" :description="`${campaign.public_code} · ${campaign.advertiser.name}`"/><Link :href="`/admin/ad-campaigns/${campaign.id}/edit`"><Button variant="outline">Edit</Button></Link></div><div class="grid gap-4 md:grid-cols-3"><div class="rounded-xl border p-5"><p class="text-sm text-muted-foreground">Status</p><p class="text-xl font-semibold capitalize">{{campaign.status}}</p></div><div class="rounded-xl border p-5"><p class="text-sm text-muted-foreground">Placements</p><p class="text-xl font-semibold">{{campaign.placements.length}}</p></div><div class="rounded-xl border p-5"><p class="text-sm text-muted-foreground">Creatives</p><p class="text-xl font-semibold">{{campaign.creatives.length}}</p></div></div><div class="rounded-xl border p-5"><h2 class="font-semibold">Approval workflow</h2><p v-if="campaign.rejection_reason" class="mt-2 text-sm text-destructive">{{campaign.rejection_reason}}</p><div class="mt-4 flex gap-2"><Button v-if="['draft','rejected'].includes(campaign.status)" @click="submit">Submit for approval</Button><Button v-if="campaign.status==='submitted'" @click="decide('approve')">Approve</Button><Button v-if="campaign.status==='submitted'" variant="destructive" @click="decide('reject')">Reject</Button></div></div><div class="rounded-xl border p-5"><h2 class="font-semibold">Assigned placements</h2><ul class="mt-3 space-y-2"><li v-for="x in campaign.placements">{{x.name}} — {{x.location}} / {{x.format}}</li></ul></div></div></template>